"""A readable spatial and teaching report from actual curated-hall evidence."""
from pathlib import Path
import json,html,hashlib
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'doc/book/iterations/2026-10-07-forces-curated-progression'
def read(p):return json.loads(p.read_text(encoding='utf8'))
def esc(s):return html.escape(str(s))
def build():
    data=read(ROOT/'commons/artifacts/force_halls/curation.json');halls=data['halls']
    catalog=read(ROOT/'doc/book/iterations/2026-10-07-forces-ten-more/catalog.json')
    names={a['token']:a['title'] for a in catalog}
    names.update(force_point_direction='Point / displacement',force_point_addition='Point / addition',force_point_projection='Point / projection')
    reports=[(p,read(p)) for p in sorted((OUT/'after').glob('*/report.json'))]+[(p,read(p)) for p in sorted((OUT/'tests').glob('*/report.json'))]
    assert len(reports)==17,'Expected thirteen layouts, three point lessons and one route test'
    assert all(r['passed'] for _,r in reports),'Repair failures before publishing a finished report'
    assert all('SCRIPT ERROR' not in (p.parent/'engine.log').read_text(encoding='utf8',errors='replace') for p,_ in reports),'A run contains a script error'
    checks=sum(len(r['checks']) for _,r in reports)
    evidence={'checks':checks,'passed':True,'reports':[{'path':p.relative_to(OUT).as_posix(),'scope':r.get('scope'),'checks':len(r['checks'])} for p,r in reports],
              'limits':'Desktop Godot 4.6, supplied XRTools rig and input events. No physical headset, Quest frame-time, all older mechanisms, or learner comprehension claim.'}
    (OUT/'verification.json').write_text(json.dumps(evidence,indent=2),encoding='utf8')
    statuses=[{'map':r.get('room',p.parent.name),'passed':r['passed'],'report':p.relative_to(OUT).as_posix()} for p,r in reports]
    (OUT/'verification-status.json').write_text(json.dumps(statuses,indent=2),encoding='utf8')
    (OUT/'capture-status.json').write_text(json.dumps([s for s in statuses if s['report'].startswith('after/')],indent=2),encoding='utf8')
    keep=data['keep_disposition'];placed=sum(x['status']=='main walk' for x in keep)
    alternatives=sum(x['status']=='collection alternative' for x in keep)
    body=['''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Forces — a point gains capacities</title>
<style>:root{color-scheme:light;--ink:#28252b;--paper:#f3f0e9;--rose:#9d4366;--line:#d9d2c7}*{box-sizing:border-box}html{scroll-behavior:auto}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.65 system-ui,sans-serif}a{color:var(--rose)}header,main,footer{max-width:1420px;padding:50px 5vw;margin:auto}.eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:var(--rose)}h1{font:clamp(38px,6vw,78px)/1.04 Georgia,serif;max-width:950px;margin:20px 0}h2{font:clamp(28px,4vw,44px)/1.1 Georgia,serif}h3{font:24px/1.3 Georgia,serif}.lead{font:24px/1.5 Georgia,serif;max-width:900px}.note{max-width:920px}.facts{display:flex;flex-wrap:wrap;gap:34px;margin:30px 0}.facts b{display:block;font:42px Georgia,serif}.facts span{font-size:13px}.links{display:flex;gap:20px;flex-wrap:wrap;margin-top:20px}.route{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:12px}.route a{display:block;padding:17px;background:#fff9;border:1px solid var(--line);text-decoration:none;color:var(--ink)}.route small{display:block;color:var(--rose)}.route span{font-size:14px}.hall{padding:45px 0 65px;border-top:1px solid var(--line);scroll-margin-top:25px}.hallhead{display:flex;justify-content:space-between;align-items:baseline;gap:20px}.hallhead h2{margin:12px 0 22px}.hallnav{white-space:nowrap;font-size:13px}.wide{width:100%;aspect-ratio:3/2;object-fit:contain;display:block;background:#242631}.picture{margin:0}.picture a{display:block}.picture figcaption{font-size:13px;color:#655f64;padding:9px 0}.twocol{display:grid;grid-template-columns:1.6fr 1fr;gap:30px;margin-top:24px}.twocol img{width:100%;display:block}.plan{background:#fff9;border:1px solid var(--line);padding:12px}.plan svg{display:block;width:100%;height:260px}.legend{font-size:12px;margin:4px 0}.lesson{background:#fff9;padding:25px;border-left:4px solid var(--rose);margin-top:24px}.lesson p:last-child{margin-bottom:0}.lesson b{color:var(--rose)}.list{list-style:none;padding:0}.list li{margin:10px 0;padding-bottom:10px;border-bottom:1px solid var(--line);font-size:14px}.list small{color:var(--rose);display:block}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:12px}.comparison img{width:100%}details{margin:20px 0}summary{cursor:pointer;color:var(--rose)}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:10px;border-bottom:1px solid var(--line);vertical-align:top}code{font-size:13px;overflow-wrap:anywhere}.narrow{max-width:930px}.pill{display:inline-block;background:#e6dbe0;padding:3px 9px;border-radius:16px;font-size:12px}@media(max-width:750px){.twocol,.comparison{grid-template-columns:1fr}.hallhead{display:block}header,main,footer{padding:30px 20px}.facts{gap:20px}.wide{aspect-ratio:auto}.route{grid-template-columns:1fr 1fr}}
</style><header><div class="eyebrow">Endless Museum / Forces / 7 October 2026</div><h1>A point gains capacities.</h1><p class="note"><a href="../2026-10-07-forces-teleport-and-body/index.html">New: teleport controls and the body-worn vector visor →</a></p><p class="lead">Thirteen halls give one experiment the foreground, then let neighbouring artifacts test, compare or complicate its principle.</p>''']
    body.append(f'<div class="facts"><span><b>13</b>real museum halls</span><span><b>{len(keep)}</b>Keep choices preserved</span><span><b>1</b>tutorial artifact per hall</span><span><b>{checks}</b>passing checks in this pass</span></div>')
    body.append(f'''<p class="note">The walk uses {placed} of your Keeps, plus the new point lessons and selected supporting pieces. {alternatives} Keeps remain available as collection alternatives; two are empty scene records. The ten recent trials now sit beside the subjects they develop. The existing thirteen-hall order is retained.</p>
<p class="note">The first three rooms reuse the earlier <code>PointBody</code> for displacement, addition and projection. Later rooms return to the point as a dynamic body, a receiver and a source of thrust. The spring handle, support cube and phase array remain useful exceptions: their material differences are part of the lesson.</p>
<div class="links"><a href="#route">See the progression ↓</a><a href="#visit">Test in VR</a><a href="#selection">Where the Keeps went</a><a href="http://localhost:3003/research/forces-review/index.html">Change collection choices ↗</a><a href="verification.json">Verification record</a></div>
<details id="visit"><summary>Open this route in the museum</summary><p>Open <code>commons/scenes/forces_curated_museum.tscn</code> in Godot and run the scene. It opens the normal Endless Museum at the first Forces hall. The canonical Forces maps also contain these arrangements. Use the next and previous museum portals.</p><p>Try the point at hand height, the spacing between controls, and the flight court. Desktop and supplied XRTools interactions were checked; physical headset reach, comfort and Quest performance still need your visit.</p></details>
</header><main><section id="route"><div class="eyebrow">The teaching path</div><h2>Relation → motion → consequence → capacity</h2><p class="narrow">The small learning thread is cumulative. A position becomes a displacement; compatible displacements combine. Velocity then carries a body beyond the moment of input. Fields, resistance, restoration, contacts and other bodies alter that journey. The final court gives those relations back to the visitor as usable powers.</p><div class="route">''')
    for r in halls:body.append(f'<a href="#{r["map"]}"><small>{r["number"]:02d}</small><strong>{esc(r["title"])}</strong><br><span>{esc(r["principle"])}</span></a>')
    body.append('</div><p class="narrow"><b>Writing status.</b> Each hall now has a short <code>FORCES_LESSON.md</code> contract naming its one tutorial artifact, what returns, what changes, and an independent student check. These are plans for the next manuscript pass. The full <code>tutorial.md</code> and reflective <code>final.md</code> have not been presented as newly rewritten or tested here.</p></section>')
    for i,r in enumerate(halls):
        m=r['map'];n=r['number'];w,d=r['size'];hero=r['tutorial_artifact'];prefix=f'after/{m}/'
        lessons=OUT/'lessons';lessons.mkdir(exist_ok=True)
        (lessons/f'{m}.md').write_text((ROOT/f'commons/maps/{m}/FORCES_LESSON.md').read_text(encoding='utf8'),encoding='utf8')
        nav=(f'<a href="#{halls[i-1]["map"]}">← Previous</a> · ' if i else '')+(f'<a href="#{halls[i+1]["map"]}">Next →</a>' if i<len(halls)-1 else '<a href="#route">Back to route</a>')
        body.append(f'<section class="hall" id="{m}"><div class="eyebrow">Hall {n:02d} / {esc(m)}</div><div class="hallhead"><h2>{esc(r["title"])}</h2><nav class="hallnav">{nav}</nav></div><figure class="picture"><a href="{prefix}above.png"><img class="wide" src="{prefix}above.png" loading="lazy" alt="Elevated Godot view of {esc(r["title"])}"></a><figcaption>Actual Godot museum capture. Elevated camera shows spacing; open the image at full size.</figcaption></figure>')
        body.append(f'<div class="twocol"><figure class="picture"><a href="{prefix}entry.png"><img src="{prefix}entry.png" loading="lazy" alt="Eye-height entry to {esc(r["title"])}"></a><figcaption>From the entrance, at 1.7 m eye height.</figcaption></figure><div class="plan"><svg viewBox="-1 -1 {w+2} {d+2}" role="img" aria-label="Plan of the hall"><rect x="0" y="0" width="{w}" height="{d}" fill="#f3f0e9" stroke="#777" stroke-width=".2"/>')
        for a in r['placements']:
            x,z=a['cell'];zw,zd=a['zone'];c='#ad6380' if a['role']=='tutorial' else '#aaa398'
            body.append(f'<rect x="{x-zw/2}" y="{z-zd/2}" width="{zw}" height="{zd}" fill="{c}" opacity=".38" stroke="{c}" stroke-width=".15"><title>{esc(names.get(a["token"],a["token"]))}</title></rect>')
        coords=' '.join(f'{x},{z}' for x,z in r['walk'])
        body.append(f'<polyline points="{coords}" fill="none" stroke="#26272a" stroke-width=".16" stroke-dasharray=".5 .35"/><circle cx="{r["walk"][0][0]}" cy="{r["walk"][0][1]}" r=".45" fill="#26272a"/></svg><p class="legend">Rose: tutorial encounter. Grey: comparisons. Dashed: checked walking route. Diagram shows intended activity zones, not a complete collision survey.</p><p class="legend">{w} × {d} m authored floor. {r["before_count"]} → {r["after_count"]} map artifact placements; automatic museum furniture and internal parts are counted separately.</p></div></div>')
        body.append(f'<div class="lesson"><span class="pill">Tutorial / {esc(names.get(hero,hero))}</span><h3>{esc(r["principle"])}</h3><p>{esc(r["lesson"])}</p><p><b>Carry onward:</b> {esc(r["carry"])}</p><details><summary>Independent student check</summary><p>{esc(r["independent_check"])}</p></details></div><ul class="list">')
        for a in r['placements']:
            if a['role']=='tutorial':continue
            body.append(f'<li><small>{esc(a["role"])}</small>{esc(names.get(a["token"],a["token"]))} · <a href="http://localhost:3003/research/forces-review/index.html#{a["token"]}">Inspect / change choice</a></li>')
        body.append('</ul>')
        if n==13:body.append('<p class="narrow">The earlier field crossing, loose force cubes, invisible hill and familiar court apparatus remain. This last room is intentionally richer: the tutorial follows the thrust-point connection; the other mechanisms are available for experiments.</p>')
        if (OUT/'before'/m/'above.png').exists():body.append(f'<details><summary>Compare the previous arrangement</summary><div class="comparison"><figure class="picture"><img src="before/{m}/above.png" loading="lazy" alt="Before arrangement"><figcaption>Before — real museum capture.</figcaption></figure><figure class="picture"><img src="{prefix}above.png" loading="lazy" alt="After arrangement"><figcaption>After — the new focal point and separate comparisons.</figcaption></figure></div></details>')
        body.append(f'<p class="legend"><a href="{prefix}report.json">Placement evidence</a> · <a href="lessons/{m}.md">Lesson contract</a></p></section>')
    body.append('<section id="selection"><div class="eyebrow">A collection can exceed a route</div><h2>Your Keeps remain available.</h2><p>The decisions below are a saved snapshot from your review page, including its notes. Your original browser choices are unchanged. A collection alternative is available for a later swap; it has not been deleted.</p><div class="links"><a href="user-choices.json" download>Original review choices</a><a href="curation.json" download>Editable hall plan</a><a href="http://localhost:3003/research/forces-review/index.html">Open the collection</a></div><details><summary>All 107 Keeps and their places</summary><table><thead><tr><th>Artifact</th><th>Place in this pass</th></tr></thead><tbody>')
    for a in sorted(keep,key=lambda a:(a['status'],a['title'])):
        halllinks=' · '.join(f'<a href="#{m}">{next(r["number"] for r in halls if r["map"]==m):02d}</a>' for m in a['halls'])
        body.append(f'<tr><td><a href="http://localhost:3003/research/forces-review/index.html#{a["token"]}">{esc(a["title"])}</a></td><td>{esc(a["status"])} {halllinks}</td></tr>')
    body.append(f'</tbody></table></details><p class="narrow"><b>Evidence and limits.</b> {checks} assertions pass: thirteen room layouts, three point interactions, and thirteen forward hall arrivals plus a return. Placement checks sample a standing capsule along the stated route. The new turret bay also acquired a real pooled target. The earlier ten-trial physics tests and flight-court tests remain separate evidence. Older support artifacts were positioned and visually inspected; their complete mechanisms were not all revalidated. Headset reach, comfort and Quest performance remain open.</p><p><a href="verification.json">Read exact test scopes</a> · <a href="../2026-10-07-forces-ten-more/runtime-checks.json">Earlier trial checks</a> · <a href="source-hashes.json">Source snapshot</a></p></section></main><footer>Endless Museum<br><span class="eyebrow">always another room</span></footer></html>')
    result=''.join(body).replace('.twocol img{width:100%;display:block}', '.twocol img{width:100%;display:block;aspect-ratio:3/2;object-fit:contain}').replace('.comparison img{width:100%}', '.comparison img{width:100%;aspect-ratio:3/2;object-fit:contain}')
    (OUT/'index.html').write_text(result,encoding='utf8')
    public=ROOT.parent/'ada_encyclopedia/public/research/forces-curated'
    public.mkdir(parents=True,exist_ok=True)
    served=result.replace('<meta charset="utf-8">','<meta charset="utf-8"><base href="/book-review/doc/book/iterations/2026-10-07-forces-curated-progression/">').replace('href="#','href="/research/forces-curated/index.html#')
    (public/'index.html').write_text(served,encoding='utf8')
    paths=list((ROOT/'commons/artifacts/force_halls').glob('*'))
    paths += [ROOT/f'commons/maps/{r["map"]}/map_data.json' for r in halls]+[ROOT/f'commons/maps/{r["map"]}/FORCES_LESSON.md' for r in halls]
    paths += [ROOT/p for p in ['tools/curate_force_halls.py','tools/probes/forces_layout.gd','tools/probes/forces_point_lessons.gd','tools/probes/forces_curated_route.gd','tools/review_force_halls.py','tools/publish_curated_forces.py','commons/scenes/forces_curated_museum.tscn','commons/maps/sequences/forces.json','commons/artifacts/registry/force_halls.json']]
    hashes={p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in paths if p.is_file()}
    (OUT/'source-hashes.json').write_text(json.dumps(hashes,indent=2),encoding='utf8')
    print(f'Published {len(halls)} halls, {checks} checks, {placed} selected Keeps and {alternatives} alternatives.')
if __name__=='__main__':build()
